  <style>
    :root{
      --ink: #07060a;
      --paper: #0b0712;
      --paper2:#0f0a18;
      --cream:#120b1f;
      --mist: rgba(255,255,255,0.10);

      --purple: #6d2cff;           /* royal purple */
      --purple2:#3a12a7;
      --gold: #ffd400;             /* neon gold */
      --gold2:#ffb700;
      --white: #f7f3ff;
      --slate: rgba(247,243,255,0.72);
      --shadow: rgba(0,0,0,0.55);

      --font-display: "Playfair Display", Georgia, serif;
      --font-body: "Instrument Sans", system-ui, -apple-system, Segoe UI, sans-serif;
      --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

      --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
      --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);

      --radius: 18px;
      --radius2: 28px;
    }

    *{box-sizing:border-box;margin:0;padding:0}
    html{scroll-behavior:smooth}
    html{
      scrollbar-color:#9d1f16 rgba(17,17,15,0.12);
      scrollbar-width:auto;
    }
    ::-webkit-scrollbar{width:14px;height:14px}
    ::-webkit-scrollbar-track{
      background:linear-gradient(180deg,rgba(17,17,15,0.12),rgba(210,168,77,0.14));
      border-left:1px solid rgba(17,17,15,0.12);
    }
    ::-webkit-scrollbar-thumb{
      background:linear-gradient(180deg,#9d1f16,#d2a84d);
      border:3px solid rgba(244,239,229,0.92);
      box-shadow:0 0 16px rgba(157,31,22,0.38);
    }
    ::-webkit-scrollbar-thumb:hover{background:linear-gradient(180deg,#11110f,#9d1f16)}
    body{
      font-family:var(--font-body);
      /* background replaced by living canvas + overlay */
      background: transparent;
      color:var(--white);
      line-height:1.65;
      overflow-x:hidden;
      -webkit-font-smoothing:antialiased;
      position: relative;
    }

    /* Living canvas styling */
    #bg-canvas {
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100vh;
      z-index: -2;
      background: linear-gradient(180deg, var(--paper) 0%, var(--paper2) 100%);
    }

    /* Maintain the lighting effects as an overlay */
    .bg-lighting {
      position: fixed;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      background: radial-gradient(1200px 800px at 20% -10%, rgba(109,44,255,0.25), transparent 55%),
                  radial-gradient(900px 700px at 90% 20%, rgba(255,212,0,0.12), transparent 55%);
    }

    a{color:inherit}
    .container{max-width:1240px;margin:0 auto;padding:0 24px}

    /* Cursor aura (subtle, cheap GPU) */
    .aura{
      position:fixed;
      inset:0;
      pointer-events:none;
      z-index:9999;
      mix-blend-mode:screen;
    }
    .aura::before{
      content:"";
      position:absolute;
      width:520px;height:520px;
      left:var(--mx, 50%); top:var(--my, 50%);
      transform:translate(-50%,-50%);
      background: radial-gradient(circle at center,
                rgba(109,44,255,0.22) 0%,
                rgba(255,212,0,0.16) 28%,
                transparent 62%);
      filter: blur(10px);
      opacity:0.85;
      transition: opacity 200ms ease;
    }
    @media (prefers-reduced-motion: reduce){
      .aura{display:none}
    }

    /* Cinematic opener */
    .cinematic-opener{
      position:fixed;inset:0;
      background: radial-gradient(900px 700px at 30% 20%, rgba(109,44,255,0.35), transparent 55%),
                  radial-gradient(900px 700px at 80% 60%, rgba(255,212,0,0.14), transparent 55%),
                  linear-gradient(180deg, #05040a 0%, #080512 100%);
      z-index:10000;
      display:flex;align-items:center;justify-content:center;flex-direction:column;
      animation: openerFadeOut 1.05s var(--ease-out-expo) 3.9s forwards;
      pointer-events:none;
    }
    .opener-content{position:relative;z-index:2;text-align:center;padding:24px}
    .opener-kicker{
      font-family:var(--font-mono);
      font-size:0.72rem;
      letter-spacing:0.22em;
      text-transform:uppercase;
      color:rgba(247,243,255,0.75);
      opacity:0; transform: translateY(16px);
      animation: slideUp 0.9s var(--ease-out-expo) 0.35s forwards;
    }
    .opener-title{
      font-family:var(--font-display);
      font-size:clamp(2.4rem, 7vw, 4.8rem);
      line-height:1.05;
      margin:18px 0 14px;
      color:var(--white);
      opacity:0; transform: translateY(20px);
      animation: slideUp 1.05s var(--ease-out-expo) 0.75s forwards;
    }
    .opener-title em{font-style:italic;color:var(--gold)}
    .opener-divider{
      width:0;height:1px;margin:20px auto;
      background: linear-gradient(90deg, transparent, rgba(255,212,0,0.95), transparent);
      animation: expandLine 1.3s var(--ease-out-expo) 1.2s forwards;
    }
    .opener-sub{
      font-size:1.02rem;color:rgba(247,243,255,0.78);
      max-width:720px;margin:0 auto;
      opacity:0; animation: fadeIn 1.2s var(--ease-out-expo) 1.55s forwards;
    }
    .opener-badge{
      margin-top:26px;
      display:inline-flex; align-items:center; gap:10px;
      padding:10px 14px;
      border:1px solid rgba(255,255,255,0.10);
      background: rgba(10,8,18,0.55);
      border-radius:999px;
      opacity:0; animation: fadeIn 0.9s var(--ease-out-expo) 2.05s forwards;
    }
    .badge-dot{
      width:10px;height:10px;border-radius:50%;
      background: radial-gradient(circle at 35% 30%, #fff, var(--gold));
      box-shadow: 0 0 18px rgba(255,212,0,0.45);
    }
    .badge-text{
      font-family:var(--font-mono);
      font-size:0.72rem;
      letter-spacing:0.14em;
      text-transform:uppercase;
      color:rgba(247,243,255,0.78);
    }
    .progress-bar{
      position:fixed;bottom:34px;left:50%;
      transform:translateX(-50%);
      width:220px;height:2px;border-radius:2px;
      background: rgba(255,255,255,0.10);
      overflow:hidden; z-index:10001;
      animation: fadeOut 0.6s var(--ease-out-expo) 3.4s forwards;
    }
    .progress-fill{
      height:100%; width:0;
      background: linear-gradient(90deg, var(--purple), var(--gold));
      animation: progressFill 3.4s var(--ease-out-quart) forwards;
    }

    @keyframes slideUp{to{opacity:1;transform:translateY(0)}}
    @keyframes fadeIn{to{opacity:1}}
    @keyframes expandLine{to{width:240px}}
    @keyframes openerFadeOut{to{opacity:0;visibility:hidden}}
    @keyframes progressFill{to{width:100%}}
    @keyframes fadeOut{to{opacity:0}}

    /* Nav */
    .nav{
      position:fixed;top:0;left:0;right:0;
      z-index:1000;
      padding:18px 0;
      transition: all 380ms var(--ease-out-expo);
    }
    .nav.scrolled{
      padding:12px 0;
      background: rgba(10,8,18,0.66);
      backdrop-filter: blur(16px);
      box-shadow: 0 10px 40px rgba(0,0,0,0.25);
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .nav-inner{display:flex;align-items:center;justify-content:space-between;gap:18px}
    .brand{
      display:flex;flex-direction:column;gap:3px;
      text-decoration:none;
    }
    .brand .name{
      font-family:var(--font-display);
      font-size:1.08rem;
      font-weight:700;
      letter-spacing:0.01em;
      color:var(--white);
    }
    .brand .sub{
      font-family:var(--font-mono);
      font-size:0.64rem;
      letter-spacing:0.18em;
      text-transform:uppercase;
      color:rgba(247,243,255,0.65);
    }
    .nav-links{
      display:flex;gap:26px;list-style:none;
      align-items:center;
    }
    .nav-links a{
      text-decoration:none;
      font-size:0.9rem;
      color:rgba(247,243,255,0.74);
      transition: color 220ms ease, transform 220ms ease;
      display:inline-flex; align-items:center; gap:10px;
      padding:10px 8px;
    }
    .nav-links a:hover{color:var(--white); transform: translateY(-1px)}
    .nav-cta{
      text-decoration:none;
      display:inline-flex;align-items:center;gap:10px;
      padding:12px 16px;
      border-radius:999px;
      background: linear-gradient(90deg, rgba(109,44,255,0.95), rgba(255,212,0,0.95));
      color:#080512;
      font-weight:800;
      letter-spacing:0.06em;
      text-transform:uppercase;
      font-size:0.78rem;
      box-shadow: 0 18px 36px rgba(0,0,0,0.35);
      transition: transform 240ms var(--ease-out-expo), filter 240ms var(--ease-out-expo);
    }
    .nav-cta:hover{transform: translateY(-2px); filter: brightness(1.06)}
    .nav-cta svg{width:16px;height:16px}

    /* Mobile menu */
    .menu-btn{
      display:none;
      border:1px solid rgba(255,255,255,0.12);
      background: rgba(10,8,18,0.40);
      color:var(--white);
      padding:10px 12px;
      border-radius:12px;
      cursor:pointer;
      align-items:center; gap:10px;
    }
    .menu-btn svg{width:18px;height:18px}
    .drawer{
      position:fixed;top:0;right:0;height:100vh;width:min(420px, 92vw);
      background: rgba(12,9,20,0.92);
      backdrop-filter: blur(18px);
      border-left:1px solid rgba(255,255,255,0.10);
      transform: translateX(110%);
      transition: transform 420ms var(--ease-out-expo);
      z-index:1200;
      padding:22px 18px;
      display:flex; flex-direction:column; gap:10px;
    }
    .drawer.open{transform: translateX(0)}
    .drawer-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
    .drawer a{
      text-decoration:none;
      padding:14px 14px;
      border-radius:14px;
      border:1px solid rgba(255,255,255,0.10);
      background: rgba(255,255,255,0.04);
      color:rgba(247,243,255,0.85);
      font-weight:600;
    }
    .drawer a:hover{background: rgba(255,255,255,0.07)}
    .drawer .close{
      border:1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.06);
      color:var(--white);
      padding:10px 12px;
      border-radius:12px;
      cursor:pointer;
      display:inline-flex;align-items:center;gap:8px;
    }
    .backdrop{
      position:fixed;inset:0;
      background: rgba(0,0,0,0.55);
      z-index:1100;
      opacity:0; pointer-events:none;
      transition: opacity 260ms ease;
    }
    .backdrop.show{opacity:1; pointer-events:auto}

    /* Hero */
    .hero{
      min-height:100vh;
      display:flex;align-items:center;
      position:relative;
      padding:120px 0 70px;
      overflow:hidden;
    }
    .hero::before{
      content:"";
      position:absolute;inset:-120px -120px -120px -120px;
      background:
        radial-gradient(700px 520px at 20% 15%, rgba(109,44,255,0.46), transparent 58%),
        radial-gradient(740px 560px at 80% 35%, rgba(255,212,0,0.18), transparent 58%),
        radial-gradient(900px 700px at 50% 120%, rgba(255,255,255,0.06), transparent 60%);
      filter: blur(10px);
      opacity:0.9;
      pointer-events:none;
    }
    .hero-grid{
      position:relative;z-index:2;
      display:grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap:34px;
      align-items:center;
    }
    .kicker{
      display:inline-flex;align-items:center;gap:12px;
      font-family:var(--font-mono);
      font-size:0.72rem;
      letter-spacing:0.22em;
      text-transform:uppercase;
      color:rgba(255,212,0,0.92);
      margin-bottom:18px;
    }
    .kicker::before{
      content:"";
      width:44px;height:1px;
      background: linear-gradient(90deg, rgba(255,212,0,0.95), rgba(109,44,255,0.75));
    }
    .hero h1{
      font-family:var(--font-display);
      font-size: clamp(2.6rem, 6.4vw, 5.1rem);
      line-height:1.05;
      font-weight:650;
      margin-bottom:16px;
      letter-spacing:0.01em;
    }
    .hero h1 em{font-style:italic;color:var(--gold)}
    .hero p{
      font-size:1.08rem;
      color:rgba(247,243,255,0.78);
      max-width:62ch;
      margin-bottom:24px;
    }
    .hero-actions{
      display:flex;gap:12px;flex-wrap:wrap;
      margin-top:12px;
    }
    .btn{
      display:inline-flex;align-items:center;gap:10px;
      padding:14px 18px;
      border-radius:999px;
      text-decoration:none;
      font-weight:800;
      letter-spacing:0.06em;
      text-transform:uppercase;
      font-size:0.78rem;
      transition: transform 240ms var(--ease-out-expo), box-shadow 240ms var(--ease-out-expo), filter 240ms ease;
      will-change: transform;
    }
    .btn-primary{
      background: linear-gradient(90deg, rgba(255,212,0,0.95), rgba(109,44,255,0.95));
      color:#07060a;
      box-shadow: 0 20px 44px rgba(0,0,0,0.38);
    }
    .btn-primary:hover{transform: translateY(-2px); filter: brightness(1.05)}
    .btn-ghost{
      border:1px solid rgba(255,255,255,0.16);
      background: rgba(255,255,255,0.04);
      color:rgba(247,243,255,0.9);
    }
    .btn-ghost:hover{transform: translateY(-2px); box-shadow: 0 16px 34px rgba(0,0,0,0.25)}
    .btn svg{width:16px;height:16px}

    .hero-card{
      border-radius: var(--radius2);
      background:
        linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      border:1px solid rgba(255,255,255,0.12);
      box-shadow: 0 30px 70px rgba(0,0,0,0.38);
      overflow:hidden;
      position:relative;
    }
    .hero-card::before{
      content:"";
      position:absolute;inset:0;
      background:
        radial-gradient(500px 340px at 15% 20%, rgba(109,44,255,0.35), transparent 55%),
        radial-gradient(520px 360px at 85% 55%, rgba(255,212,0,0.18), transparent 55%);
      opacity:0.9;
      pointer-events:none;
    }
    .hero-card-inner{
      position:relative;z-index:2;
      padding:18px;
    }
    .quick-launch{
      display:flex;flex-direction:column;gap:12px;
    }
    .panel-title{
      font-family:var(--font-mono);
      font-size:0.68rem;
      letter-spacing:0.18em;
      text-transform:uppercase;
      color:rgba(247,243,255,0.72);
      margin-bottom:6px;
    }
    .launch-item{
      display:flex;align-items:flex-start;justify-content:space-between;gap:14px;
      padding:14px 14px;
      border-radius:16px;
      border:1px solid rgba(255,255,255,0.10);
      background: rgba(0,0,0,0.18);
      text-decoration:none;
      transition: transform 240ms var(--ease-out-expo), background 240ms ease, border-color 240ms ease;
    }
    .launch-item:hover{
      transform: translateY(-2px);
      background: rgba(255,255,255,0.06);
      border-color: rgba(255,212,0,0.24);
    }
    .launch-left{display:flex;flex-direction:column;gap:4px}
    .launch-name{font-weight:850;letter-spacing:0.01em}
    .launch-desc{font-size:0.9rem;color:rgba(247,243,255,0.72);line-height:1.45}
    .launch-tag{
      font-family:var(--font-mono);
      font-size:0.68rem;
      letter-spacing:0.12em;
      text-transform:uppercase;
      color:rgba(255,212,0,0.92);
      padding-top:2px;
      white-space:nowrap;
    }

    /* Section styling */
    section{padding:74px 0}
    .section-head{
      display:flex;align-items:flex-end;justify-content:space-between;
      gap:16px;
      margin-bottom:26px;
    }
    .section-head h2{
      font-family:var(--font-display);
      font-size: clamp(1.8rem, 3.4vw, 2.7rem);
      line-height:1.15;
      font-weight:650;
    }
    .section-head p{
      color:rgba(247,243,255,0.74);
      max-width:72ch;
      font-size:1.02rem;
    }

    .grid-3{
      display:grid;
      grid-template-columns: repeat(3, 1fr);
      gap:16px;
    }
    .card{
      border-radius: var(--radius);
      background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      border:1px solid rgba(255,255,255,0.12);
      padding:18px;
      box-shadow: 0 24px 60px rgba(0,0,0,0.28);
      position:relative;
      overflow:hidden;
      transition: transform 260ms var(--ease-out-expo), border-color 260ms ease, background 260ms ease;
    }
    .card::before{
      content:"";
      position:absolute;inset:0;
      background: radial-gradient(540px 380px at 15% 10%, rgba(109,44,255,0.22), transparent 60%);
      opacity:0.75;
      pointer-events:none;
