      font-size:1.05rem;
      font-weight:900;
      margin-bottom:8px;
    }
    .card p{
      position:relative;z-index:2;
      color:rgba(247,243,255,0.74);
      font-size:0.98rem;
    }
    .pill{
      position:relative;z-index:2;
      display:inline-flex;align-items:center;gap:10px;
      font-family:var(--font-mono);
      font-size:0.66rem;
      letter-spacing:0.18em;
