    .bottom{
      display:flex;align-items:center;justify-content:space-between;gap:12px;
      flex-wrap:wrap;
      border-top: 1px solid rgba(255,255,255,0.08);
      padding-top:16px;
      color:rgba(247,243,255,0.62);
      font-family:var(--font-mono);
      font-size:0.72rem;
      letter-spacing:0.06em;
    }
    .legal{display:flex;gap:14px;flex-wrap:wrap}
    .legal a{color:rgba(247,243,255,0.62);text-decoration:none}
    .legal a:hover{color:var(--gold)}

    /* Reveal */
    .reveal{
      opacity:0;
      transform: translateY(26px);
      transition: opacity 700ms var(--ease-out-expo), transform 700ms var(--ease-out-expo);
    }
    .reveal.visible{opacity:1;transform: translateY(0)}
    .stagger-1{transition-delay:80ms}
    .stagger-2{transition-delay:160ms}
    .stagger-3{transition-delay:240ms}

    /* Responsive */
    @media (max-width: 980px){
      .hero-grid{grid-template-columns: 1fr; gap:18px}
      .grid-3{grid-template-columns: 1fr}
      .steps{grid-template-columns:1fr}
      .stats-grid{grid-template-columns:1fr 1fr}
      .nav-links{display:none}
      .menu-btn{display:inline-flex}
      .cta-box{flex-direction:column;align-items:flex-start}
      .foot-grid{grid-template-columns:1fr}
