  <script>
    // ===== Cursor aura tracking (respects reduced motion) =====
    (function(){
      const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (reduce) return;
      const aura = document.querySelector('.aura');
      if (!aura) return;

      let raf = null;
      window.addEventListener('pointermove', (e) => {
        if (raf) cancelAnimationFrame(raf);
        raf = requestAnimationFrame(() => {
          aura.style.setProperty('--mx', e.clientX + 'px');
          aura.style.setProperty('--my', e.clientY + 'px');
        });
      }, { passive: true });
    })();

    // ===== Nav scroll state =====
    const nav = document.getElementById('nav');
    const onScroll = () => {
      if (window.scrollY > 80) nav.classList.add('scrolled');
      else nav.classList.remove('scrolled');
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

    // ===== Reveal animations =====
    const obs = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add('visible');
      });
    }, { threshold: 0.12 });

    document.querySelectorAll('.reveal').forEach(el => obs.observe(el));

    // ===== Stat counter (only where data-count exists) =====
    const animateCounter = (el, target) => {
      const duration = 1600;
      const start = 0;
      const steps = Math.max(20, Math.floor(duration / 16));
      const increment = (target - start) / steps;
      let current = start;
      let i = 0;

      const tick = () => {
        i++;
        current += increment;
        if (i >= steps) {
          el.textContent = target.toLocaleString() + "+";
          return;
        }
        el.textContent = Math.floor(current).toLocaleString();
        requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    };

    const statObs = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const v = el.getAttribute('data-count');
        if (v && !el.dataset.done) {
          el.dataset.done = "1";
          animateCounter(el, parseInt(v, 10));
        }
        statObs.unobserve(el);
      });
    }, { threshold: 0.5 });

    document.querySelectorAll('.num[data-count]').forEach(el => statObs.observe(el));

    // ===== Smooth scroll for internal anchors =====
    document.querySelectorAll('a[href^="#"]').forEach(a => {
      a.addEventListener('click', (e) => {
        const href = a.getAttribute('href');
        const target = document.querySelector(href);
        if (!target) return;
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });

    // ===== Mobile drawer =====
    const menuBtn = document.getElementById('menuBtn');
    const drawer = document.getElementById('drawer');
    const backdrop = document.getElementById('backdrop');
    const closeDrawer = document.getElementById('closeDrawer');

    const openDrawer = () => {
      drawer.classList.add('open');
      backdrop.classList.add('show');
      menuBtn.setAttribute('aria-expanded', 'true');
    };
    const closeDrawerFn = () => {
      drawer.classList.remove('open');
      backdrop.classList.remove('show');
      menuBtn.setAttribute('aria-expanded', 'false');
    };

    if (menuBtn) menuBtn.addEventListener('click', openDrawer);
    if (closeDrawer) closeDrawer.addEventListener('click', closeDrawerFn);
    if (backdrop) backdrop.addEventListener('click', closeDrawerFn);

    document.querySelectorAll('.drawerLink').forEach(link => {
      link.addEventListener('click', () => {
        closeDrawerFn();
      });
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeDrawerFn();
    });

    // ===== Editorial scroll progress =====
    (function(){
      const update = () => {
        const max = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
        document.documentElement.style.setProperty('--scroll-progress', String(Math.min(1, window.scrollY / max)));
      };
      window.addEventListener('scroll', update, { passive: true });
      window.addEventListener('resize', update);
      update();
    })();

    // ===== Lightweight living editorial field =====
    (function initEditorialField() {
      const canvas = document.querySelector('#bg-canvas');
      const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (!canvas || reduce) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      let width = 0;
      let height = 0;
      let raf = 0;
      const pointer = { x: 0, y: 0, tx: 0, ty: 0 };
      const particleCount = window.innerWidth < 760 ? 42 : 96;
      const particles = Array.from({ length: particleCount }, (_, index) => ({
        x: Math.random(),
        y: Math.random(),
        r: 0.6 + Math.random() * 1.8,
        speed: 0.08 + Math.random() * 0.2,
        phase: Math.random() * Math.PI * 2,
        color: index % 3 === 0 ? '157,31,22' : index % 3 === 1 ? '210,168,77' : '17,17,15'
      }));

      const resize = () => {
        const dpr = Math.min(window.devicePixelRatio || 1, 1.4);
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      };

      const drawWave = (time, y, amp, color) => {
        const gradient = ctx.createLinearGradient(0, y - amp * 2, width, y + amp * 2);
        gradient.addColorStop(0, 'rgba(' + color + ',0)');
        gradient.addColorStop(0.5, 'rgba(' + color + ',0.13)');
        gradient.addColorStop(1, 'rgba(' + color + ',0)');
        ctx.beginPath();
        ctx.moveTo(0, height);
        for (let x = 0; x <= width; x += 18) {
          ctx.lineTo(x, y + Math.sin(x * 0.008 + time) * amp + pointer.y * 12);
        }
        ctx.lineTo(width, height);
        ctx.closePath();
        ctx.fillStyle = gradient;
        ctx.fill();
      };

      const frame = (stamp) => {
        const time = stamp * 0.001;
        pointer.x += (pointer.tx - pointer.x) * 0.035;
        pointer.y += (pointer.ty - pointer.y) * 0.035;
        ctx.clearRect(0, 0, width, height);
        drawWave(time * 0.34, height * 0.32, 28, '157,31,22');
        drawWave(time * 0.26, height * 0.72, 34, '210,168,77');
        particles.forEach((p) => {
          const x = p.x * width + Math.sin(time * p.speed + p.phase) * 24 + pointer.x * 16;
          const y = p.y * height + Math.cos(time * p.speed + p.phase) * 16 + pointer.y * 10;
          ctx.beginPath();
          ctx.arc(x, y, p.r, 0, Math.PI * 2);
          ctx.fillStyle = 'rgba(' + p.color + ',0.16)';
          ctx.fill();
        });
        raf = requestAnimationFrame(frame);
      };

      const move = (event) => {
        pointer.tx = (event.clientX / Math.max(width, 1) - 0.5) * 2;
        pointer.ty = (event.clientY / Math.max(height, 1) - 0.5) * 2;
      };

      resize();
      window.addEventListener('resize', resize);
      window.addEventListener('pointermove', move, { passive: true });
      raf = requestAnimationFrame(frame);
    })();
  </script>
