      border:1px solid rgba(255,255,255,0.12);
      padding:18px;
      box-shadow: 0 24px 60px rgba(0,0,0,0.28);
      position:relative;
      overflow:hidden;
      transition: transform 260ms var(--ease-out-expo), border-color 260ms ease, background 260ms ease;
    }
    .card::before{
      content:"";
      position:absolute;inset:0;
      background: radial-gradient(540px 380px at 15% 10%, rgba(109,44,255,0.22), transparent 60%);
      opacity:0.75;
      pointer-events:none;
    }
    .card:hover{transform: translateY(-4px); border-color: rgba(255,212,0,0.22)}
    .card h3{
      position:relative;z-index:2;
      font-size:1.05rem;
      font-weight:900;
      margin-bottom:8px;
    }
    .card p{
      position:relative;z-index:2;
      color:rgba(247,243,255,0.74);
      font-size:0.98rem;
    }
    .pill{
      position:relative;z-index:2;
      display:inline-flex;align-items:center;gap:10px;
      font-family:var(--font-mono);
      font-size:0.66rem;
      letter-spacing:0.18em;
      text-transform:uppercase;
      color:rgba(255,212,0,0.92);
      padding:8px 12px;
      border-radius:999px;
      border:1px solid rgba(255,212,0,0.22);
      background: rgba(255,212,0,0.06);
      margin-bottom:10px;
    }
    .pill .dot{
      width:8px;height:8px;border-radius:50%;
      background: linear-gradient(180deg, var(--gold), var(--purple));
      box-shadow: 0 0 18px rgba(255,212,0,0.35);
    }

    /* Steps */
    .steps{
      display:grid;
      grid-template-columns: 1fr 1fr;
      gap:16px;
    }
    .step{
      border-radius: var(--radius);
      border:1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.04);
      padding:18px;
      transition: transform 260ms var(--ease-out-expo), border-color 260ms ease, background 260ms ease;
    }
    .step:hover{transform: translateY(-3px); border-color: rgba(109,44,255,0.26)}
    .step-top{
      display:flex;align-items:center;justify-content:space-between;gap:12px;
      margin-bottom:10px;
    }
    .step-num{
      font-family:var(--font-display);
      font-size:2.1rem;
      line-height:1;
      color:rgba(255,255,255,0.14);
      font-weight:800;
    }
    .step-title{
      font-weight:900;
      font-size:1.05rem;
    }
    .step p{color:rgba(247,243,255,0.74)}

    /* Stats bar */
    .stats{
      padding:40px 0;
      border-top: 1px solid rgba(255,255,255,0.08);
      border-bottom: 1px solid rgba(255,255,255,0.08);
      background: linear-gradient(90deg, rgba(109,44,255,0.10), rgba(255,212,0,0.06));
    }
    .stats-grid{
      display:grid;
      grid-template-columns: repeat(4, 1fr);
      gap:14px;
      align-items:stretch;
    }
    .stat{
      border-radius: 16px;
      border:1px solid rgba(255,255,255,0.10);
      background: rgba(0,0,0,0.14);
      padding:16px;
      text-align:center;
    }
    .stat .num{
      font-family:var(--font-display);
      font-size:2.3rem;
      color: var(--gold);
      font-weight:800;
      line-height:1.1;
    }
    .stat .lbl{
      font-size:0.88rem;
      color:rgba(247,243,255,0.72);
    }

    /* CTA */
    .cta{
      padding:58px 0;
    }
    .cta-box{
      border-radius: var(--radius2);
      background:
        radial-gradient(900px 520px at 20% 20%, rgba(109,44,255,0.26), transparent 58%),
        radial-gradient(900px 520px at 80% 60%, rgba(255,212,0,0.14), transparent 58%),
        linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      border:1px solid rgba(255,255,255,0.12);
      padding:22px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:18px;
      box-shadow: 0 30px 80px rgba(0,0,0,0.35);
    }
    .cta-box h3{
      font-family:var(--font-display);
      font-size:1.85rem;
      margin-bottom:6px;
    }
    .cta-box p{
      color:rgba(247,243,255,0.78);
      max-width:70ch;
    }

    /* Footer */
    footer{
      padding:50px 0 28px;
      border-top: 1px solid rgba(255,255,255,0.08);
      background: linear-gradient(180deg, rgba(0,0,0,0.18), rgba(0,0,0,0.35));
    }
    .foot-grid{
      display:grid;
      grid-template-columns: 1.8fr 1fr 1fr;
      gap:16px;
      margin-bottom:24px;
    }
    .foot h4{
      font-family:var(--font-display);
      font-size:1.25rem;
      margin-bottom:6px;
    }
    .foot small{
      font-family:var(--font-mono);
      font-size:0.66rem;
      letter-spacing:0.16em;
      text-transform:uppercase;
      color:rgba(247,243,255,0.62);
      display:block;
      margin-bottom:12px;
    }
    .foot p, .foot a{
      color:rgba(247,243,255,0.72);
      text-decoration:none;
      font-size:0.95rem;
      line-height:1.6;
    }
    .foot a:hover{color:var(--white)}
    .foot ul{list-style:none;display:flex;flex-direction:column;gap:10px;margin-top:12px}
    .bottom{
      display:flex;align-items:center;justify-content:space-between;gap:12px;
      flex-wrap:wrap;
      border-top: 1px solid rgba(255,255,255,0.08);
      padding-top:16px;
      color:rgba(247,243,255,0.62);
      font-family:var(--font-mono);
      font-size:0.72rem;
      letter-spacing:0.06em;
    }
    .legal{display:flex;gap:14px;flex-wrap:wrap}
    .legal a{color:rgba(247,243,255,0.62);text-decoration:none}
    .legal a:hover{color:var(--gold)}

    /* Reveal */
    .reveal{
      opacity:0;
      transform: translateY(26px);
      transition: opacity 700ms var(--ease-out-expo), transform 700ms var(--ease-out-expo);
    }
    .reveal.visible{opacity:1;transform: translateY(0)}
    .stagger-1{transition-delay:80ms}
    .stagger-2{transition-delay:160ms}
    .stagger-3{transition-delay:240ms}

    /* Responsive */
    @media (max-width: 980px){
      .hero-grid{grid-template-columns: 1fr; gap:18px}
      .grid-3{grid-template-columns: 1fr}
      .steps{grid-template-columns:1fr}
      .stats-grid{grid-template-columns:1fr 1fr}
      .nav-links{display:none}
      .menu-btn{display:inline-flex}
      .cta-box{flex-direction:column;align-items:flex-start}
      .foot-grid{grid-template-columns:1fr}
    }
    @media (max-width: 520px){
      .stats-grid{grid-template-columns:1fr}
      .btn{width:100%;justify-content:center}
      .nav-cta{display:none}
    }

